87	// C1: every WSL2 mode replaces the source row, with or without a container.
88	func TestWithWSLReplacesTheSourceRow(t *testing.T) {
89		tests := []struct {
90			name string
91			info wslenv.Info
92			want string
93		}{
94			{"nat", wslInfoNAT, wslSourceNAT},
95			{"mirrored", wslenv.Info{WSL2: true, Mode: wslenv.ModeMirrored}, wslSourceMirrored},
96			{"undetermined", wslenv.Info{WSL2: true}, wslSourceUndetermined},
97		}
98		ctr := &pathContainer{Name: "web", Known: true, Running: true}
99		for _, tc := range tests {
100			for _, withCtr := range []bool{false, true} {
101				name := tc.name
102				var c *pathContainer
103				if withCtr {
104					name += "/container"
