120	// C2: NAT labels the gateway row and a TTL 1 hop that is the NAT gateway.
121	func TestWithWSLNATLabelsTheWindowsHost(t *testing.T) {
122		otherHop1 := nettrace.Hop{TTL: 1, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("10.9.9.9")}
123		otherGW := netip.MustParseAddr("10.0.0.1")
124		otherGWHop1 := nettrace.Hop{TTL: 1, Kind: nettrace.HopRouter, Addr: otherGW}
125		noGateway := wslenv.Info{WSL2: true, Mode: wslenv.ModeNAT, NATInterface: "eth0"}
126		tests := []struct {
127			name     string
128			info     wslenv.Info
129			route    *pathRoute
130			hops     []nettrace.Hop
131			wantGW   bool
132			wantHop1 bool
133		}{
134			{"ttl 1 answers with the gateway", wslInfoNAT, wslRoute, []nettrace.Hop{wslHop1, wslHop2}, true, true},
135			{"ttl 1 silent", wslInfoNAT, wslRoute, []nettrace.Hop{wslHop1Quiet, wslHop2}, true, false},
136			{"no hops yet", wslInfoNAT, wslRoute, nil, true, false},
137			{"ttl 1 answers with another address", wslInfoNAT, wslRoute, []nettrace.Hop{otherHop1}, true, false},
138			{"gateway address at ttl 3 is not labelled", wslInfoNAT, wslRoute, []nettrace.Hop{wslHop1Quiet, wslHop2, wslHop3GW}, true, false},
139			{"other interface", wslInfoNAT, &pathRoute{Known: true, Interface: "wlan0", Gateway: wslGW}, []nettrace.Hop{wslHop1}, false, false},
