144			t.Run(tc.name, func(t *testing.T) {
145				steps := withWSL(pathSteps(nil, tc.route, tc.hops), tc.info)
146				if got := wslStep(steps, stepGateway).addressCell() == wslHostCell; got != tc.wantGW {
147					t.Errorf("gateway labelled = %v, want %v (cells %q)", got, tc.wantGW, wslCells(steps))
148				}
149				labelled := 0
150				for _, s := range steps {
151					if s.Kind == stepHop && s.addressCell() == wslHostCell {
152						labelled++
153						if s.Hop.TTL != 1 {
154							t.Errorf("hop with TTL %d is labelled", s.Hop.TTL)
155						}
156					}
157				}
158				if labelled > 1 || (labelled == 1) != tc.wantHop1 {
159					t.Errorf("labelled hops = %d, want hop 1 labelled = %v", labelled, tc.wantHop1)
160				}
161			})
162		}
163	}
