11	const (
12		wslSourcePrefix = "WSL2 (VM), not the Windows host"
13		windowsHostTag  = " — Windows host (virtual switch)"
14		maxPathIfaceLen = 32
15	)
16	
17	// withWSL returns a new slice of steps labelled for WSL2. The input is not
18	// modified. A zero Info (not WSL2) returns an unchanged copy.
19	func withWSL(steps []pathStep, info wslenv.Info) []pathStep {
20		out := append([]pathStep(nil), steps...)
21		if !info.WSL2 {
22			return out
23		}
24		var host netip.Addr
25		var labelled bool
26		for _, s := range out {
27			if s.Kind == stepGateway {
28				host, labelled = windowsHostGateway(info, s.Route)
29				break
30			}
31		}
32		for i := range out {
33			switch s := &out[i]; s.Kind {
34			case stepSource:
35				s.WSL = info
36			case stepGateway:
37				s.WindowsHost = labelled
38			case stepHop:
39				s.WindowsHost = labelled && s.Hop.TTL == 1 && s.Hop.Addr == host
40			}
41		}
42		return out
43	}
44	
45	// windowsHostGateway returns the NAT gateway when WSL2 is in NAT mode and
46	// route r leaves by the NAT interface through that gateway.
47	func windowsHostGateway(info wslenv.Info, r pathRoute) (netip.Addr, bool) {
48		if !info.WSL2 || info.Mode != wslenv.ModeNAT || !info.NATGateway.IsValid() {
49			return netip.Addr{}, false
50		}
51		if !r.Known || r.Gateway != info.NATGateway || r.Interface != info.NATInterface {
52			return netip.Addr{}, false
53		}
54		return info.NATGateway, true
55	}
56	
57	// wslSourceText is the source row text when WSL2 is proven.
58	func wslSourceText(info wslenv.Info) string {
59		switch info.Mode {
60		case wslenv.ModeNAT:
61			return wslSourcePrefix + " · NAT mode"
62		case wslenv.ModeMirrored:
63			return wslSourcePrefix + " · mirrored mode"
64		}
65		return wslSourcePrefix + " · WSL2 mode undetermined"
66	}
67	
68	// printable drops every non-printable rune so that text read from the host
69	// (an interface name) can never carry an escape sequence into a cell.
70	func printable(s string) string {
71		return strings.Map(func(r rune) rune {
72			if unicode.IsPrint(r) {
73				return r
74			}
75			return -1
76		}, s)
77	}
