168		steps := withWSL(pathSteps(nil, wslRoute, []nettrace.Hop{wslHop1, wslHop2}), info)
169		if got := wslStep(steps, stepSource).addressCell(); got != wslSourceMirrored {
170			t.Errorf("source cell = %q, want %q", got, wslSourceMirrored)
171		}
172		if cells := wslCells(steps); wslLabelled(cells) {
173			t.Errorf("a cell names the Windows host: %q", cells)
174		}
175	}
176	
177	// C5: an undetermined mode gets its own suffix and no Windows label.
178	func TestWithWSLUndeterminedHasNoWindowsHostLabel(t *testing.T) {
179		info := wslenv.Info{WSL2: true, NATInterface: "eth0", NATGateway: wslGW}
180		steps := withWSL(pathSteps(nil, wslRoute, []nettrace.Hop{wslHop1}), info)
181		if got := wslStep(steps, stepSource).addressCell(); got != wslSourceUndetermined {
182			t.Errorf("source cell = %q, want %q", got, wslSourceUndetermined)
183		}
184		if cells := wslCells(steps); wslLabelled(cells) {
185			t.Errorf("a cell names the Windows host: %q", cells)
186		}
187	}
188	
189	// C4: native Linux (zero Info) is identical to pathSteps alone.
190	func TestWithWSLZeroInfoChangesNothing(t *testing.T) {
191		ctr := &pathContainer{Name: "web", Known: true, Running: true}
192		for _, c := range []*pathContainer{nil, ctr} {
193			base := pathSteps(c, wslRoute, []nettrace.Hop{wslHop1, wslHop2})
194			got := withWSL(base, wslenv.Info{})
195			if !slices.Equal(got, base) {
196				t.Errorf("steps differ: %q vs %q", wslCells(got), wslCells(base))
197			}
198			for _, cell := range wslCells(got) {
199				if strings.Contains(cell, "WSL") || strings.Contains(cell, "Windows") {
200					t.Errorf("cell %q mentions WSL or Windows", cell)
201				}
202			}
203			if wslStep(got, stepSource).addressCell() != sourceLabel {
204				t.Error("source row is not this machine")
205			}
206		}
207	}
208	
209	func TestWithWSLDoesNotModifyItsInput(t *testing.T) {
210		base := pathSteps(nil, wslRoute, []nettrace.Hop{wslHop1, wslHop2})
211		snapshot := slices.Clone(base)
212		out := withWSL(base, wslInfoNAT)
213		if !slices.Equal(base, snapshot) {
214			t.Error("input steps were modified")
215		}
216		if len(out) > 0 && len(base) > 0 && &out[0] == &base[0] {
217			t.Error("result shares its backing array with the input")
218		}
219		if wslStep(out, stepSource).addressCell() != wslSourceNAT {
220			t.Error("the result is not labelled")
221		}
222	}
223	
224	// The NAT interface comes from the host's /proc: no escape sequence may reach a cell.
225	func TestWithWSLStripsControlCharactersFromTheInterface(t *testing.T) {
226		info := wslInfoNAT
227		info.NATInterface = "eth0\x1b[31m"
228		steps := withWSL(pathSteps(nil, wslRoute, []nettrace.Hop{wslHop1}), info)
229		if got := wslStep(steps, stepSource).addressCell(); !strings.Contains(got, "WSL2") {
230			t.Fatalf("source cell %q is not labelled", got)
231		}
232		for _, cell := range wslCells(steps) {
233			if strings.ContainsRune(cell, '\x1b') {
234				t.Errorf("cell %q holds an escape character", cell)
235			}
236		}
237	}
