1	package wslenv
2	
3	import (
4		"slices"
5		"strings"
6	)
7	
8	// mirroredInterface exists in the distro only under mirrored networking.
9	const mirroredInterface = "loopback0"
10	
11	// Classify turns Facts into Info. A zero Info means "not WSL2".
12	func Classify(f Facts) Info {
13		if !isWSL(f) || !strings.Contains(strings.ToUpper(f.OSRelease), "WSL2") {
14			return Info{}
15		}
16		info := Info{WSL2: true}
17		if f.NetworkingModeErr != nil {
18			return info
19		}
20		hasLoopback0 := slices.Contains(f.Interfaces, mirroredInterface)
21		switch strings.ToLower(strings.TrimSpace(f.NetworkingMode)) {
22		case "nat":
23			if hasLoopback0 {
24				return info
25			}
26			info.Mode = ModeNAT
27			if iface, gw, ok := defaultGateway(f.ProcNetRoute); ok {
28				info.NATInterface = iface
29				info.NATGateway = gw
30			}
31		case "mirrored":
32			if !hasLoopback0 {
33				return info
34			}
35			info.Mode = ModeMirrored
36		}
37		return info
38	}
39	
40	// isWSL reports whether the facts describe a WSL distro (1 or 2). Either signal
41	// suffices: WSL_DISTRO_NAME is empty under `env -i` or from a service, and
42	// osrelease alone then identifies WSL.
43	func isWSL(f Facts) bool {
44		return f.DistroName != "" || strings.Contains(strings.ToLower(f.OSRelease), "microsoft")
45	}
