117	// hopCell is the TTL of a hop row; empty for the local rows.
118	func (s pathStep) hopCell() string {
119		if s.Kind != stepHop {
120			return ""
121		}
122		return strconv.Itoa(s.Hop.TTL)
123	}
124	
125	// stepCell names the kind of row.
126	func (s pathStep) stepCell() string {
127		switch s.Kind {
128		case stepContainer:
129			return "container"
130		case stepNetwork:
131			return "network"
132		case stepBridge:
133			return "bridge"
134		case stepEngine:
135			return "engine"
136		case stepTrace:
137			return "trace"
138		case stepSource:
139			return "source"
140		case stepInterface:
141			return "interface"
142		case stepGateway:
143			return "gateway"
144		}
145		return s.Hop.Kind.String()
146	}
147	
148	// addressCell is the main text of the row.
149	func (s pathStep) addressCell() string {
150		switch s.Kind {
151		case stepContainer:
152			return s.Container.containerText()
153		case stepNetwork:
154			return s.Container.networkText()
155		case stepBridge:
156			return s.Container.Bridge
157		case stepEngine:
158			return s.Container.engineText()
159		case stepTrace:
160			return s.Container.traceText()
161		case stepSource:
162			if s.WSL.WSL2 {
163				return wslSourceText(s.WSL)
164			}
165			return sourceLabel
166		case stepInterface:
167			return s.Route.interfaceText()
168		case stepGateway:
169			return s.Route.gatewayText() + s.hostTag()
170		}
171		return addrOrDash(s.Hop.Addr) + s.hostTag()
172	}
173	
174	// hostTag is the Windows host label of a row marked by withWSL.
175	func (s pathStep) hostTag() string {
