193	// interfaceText is the interface name, followed by the source address when known.
194	func (r pathRoute) interfaceText() string {
195		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
196			return routeUndetermined
197		}
198		name := printable(r.Interface)
199		if name == "" {
