201		}
202		if !r.Source.IsValid() {
203			return name
204		}
205		return name + " (" + r.Source.String() + ")"
206	}
207	
208	// gatewayText is the gateway address, or says the destination is directly connected.
209	func (r pathRoute) gatewayText() string {
210		switch {
211		case !r.Known:
212			return routeUndetermined
213		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
214			return gatewayDirect
215		}
216		return r.Gateway.String()
217	}
218	
219	// addrOrDash formats an address, or "-" when there is none.
220	func addrOrDash(a netip.Addr) string {
221		if !a.IsValid() {
222			return "-"
223		}
224		return a.String()
225	}
